#!/usr/bin/env bash
# Auto-generated: move Council Tax page objects from the old render_council module
# addresses to the new render_service addresses, so Terraform does NOT destroy and
# recreate all 328 council page S3 objects on the first apply.
#
# Run this AFTER init against the live dev state and BEFORE terraform apply.
# Idempotent-ish: a move will error if the source address is already gone (already
# moved or already recreated); that is safe to ignore for lines that report
# "Invalid source address" / "does not match any resource".
#
# Verify afterwards with: terraform plan  (expect NO create/destroy of council-tax
# page objects; only the new electoral-register/* and james-mega-service/* adds).
set -uo pipefail

moved=0; skipped=0
mv_one() {
  if terraform state mv "$1" "$2"; then
    moved=$((moved+1))
  else
    echo "  (skipped: $1)"; skipped=$((skipped+1))
  fi
}

